#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    if (n > m) swap(n, m);
    if (n == 1) {
        cout << 6 * (m / 6) + 2 * max(0, (m % 6) - 3) << "\n";
    } else if (n == 2) {
        if (m == 2) {
            cout << 0 << "\n";
        } else if (m == 1 || m == 3 || m == 7) {
            cout << n * m - 2 << "\n";
        } else {
            cout << n * m << "\n";
        }
    } else {
        cout << ((n * m) / 2) * 2 << "\n";
    }
    return 0;
}
